from model import response
import numpy as np
# copy exact
def ex(k,T,c,q,t):
 D=np.eye(4,5,k=1)-np.eye(4,5); H=.6*np.eye(5)+c*D.T@D; l,V=np.linalg.eigh(H); v=T/k/l; om=np.sqrt(k*l-.04); d=np.exp(-.2*t)*(np.cos(om*t)+.2*np.sin(om*t)/om); C=(V*v)@V.T; R=(V*(v*d))@V.T; z=np.diag(C)[:,None]+np.diag(C)[None,:]-2*R; ph=np.exp(1j*q*np.arange(5)); return np.sum(np.real(ph[:,None]*ph.conj()[None,:])/5*np.exp(-q*q*z/2))
for c in [0,1,.5]:
 for t in [.3,.8]:print(c,t,response(1.07,.08,c,2*np.pi,t),ex(1.07,.08,c,2*np.pi,t))
PY"

/bin/bash -lc "python - <<'PY'
import json,numpy as np
x=json.load(open('data/calibration.json')); D=np.eye(4,5,k=1)-np.eye(4,5); ns=np.arange(5)
# precompute per c
cache={}
for c in {r['input']['coupling'] for r in x}:
 lam,V=np.linalg.eigh(.6*np.eye(5)+c*D.T@D); cache[c]=(lam,V)
def calc(K,e):
 c=e['coupling']; T=e['temperature']; q=e['wavevector']; t=e['delay']; lam,V=cache[c]
 var=T/(K*lam); om=np.sqrt(K*lam-.04); d=np.exp(-.2*t)*(np.cos(om*t)+.2/om*np.sin(om*t))
 C0=(V*var)@V.T; Ct=(V*(var*d))@V.T
 w=np.cos(q*(ns[:,None]-ns[None,:]))/5
 return np.sum(w*np.exp(-q*q/2*(np.diag(C0)[:,None]+np.diag(C0)[None,:]-2*Ct)))
ks=np.linspace(.8,1.2,401)
rms=np.array([np.mean([(calc(k,r['input'])-r['value'])**2 for r in x]) for k in ks])
k=ks[np.argmin(rms)]
print(k,np.sqrt(rms.min()), np.mean([(calc(k,r['input'])-r['value'])/.003 for r in x]))
for k in [1.04,1.05,1.06,1.07,1.08]:
 res=np.array([calc(k,r['input'])-r['value'] for r in x]); print(k,np.sqrt(np.mean(res**2)),np.mean(res/.003),np.max(np.abs(res)))
PY"

